export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const service = new CustomerService();
  const repository = new CustomerRepository();
  app.get('/health', async () => ({ status: 'ok', service: 'customer-service' }));
  app.post('/v1/customers', async (request, reply) => {
    const principal = await authenticate(request, 'customers:write');
    const customer = await service.create(principal.merchantId, createCustomerSchema.parse(request.body));
    return reply.code(201).send(customer);
  });
  app.get('/v1/customers', async (request) => {
    const principal = await authenticate(request, 'customers:read');
    const query = z.object({ cursor: z.string().uuid().optional(), limit: z.coerce.number().int().min(1).max(100).default(20) }).parse(request.query);
    return { data: await repository.list(principal.merchantId, query.cursor, query.limit) };
  });
  app.get('/v1/customers/:id', async (request, reply) => {
    const principal = await authenticate(request, 'customers:read');
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const customer = await repository.find(principal.merchantId, id);
    return customer ? customer : reply.code(404).send({ error: 'customer_not_found' });
  });

action.new_str:
export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const service = new CustomerService();
  const repository = new CustomerRepository();
  const erasure = new ErasureService();
  // Bodyless endpoints (e.g. erasure requests) must tolerate an empty JSON body.
  app.addContentTypeParser('application/json', { parseAs: 'string' }, (_request, body, done) => {
    if (typeof body !== 'string' || body.length === 0) { done(null, undefined); return; }
    try { done(null, JSON.parse(body)); }
    catch (error) { done(error as Error); }
  });
  app.get('/health', async () => ({ status: 'ok', service: 'customer-service' }));
  app.post('/v1/customers', async (request, reply) => {
    const principal = await authenticate(request, 'customers:write');
    const customer = await service.create(principal.merchantId, createCustomerSchema.parse(request.body));
    return reply.code(201).send(customer);
  });
  app.get('/v1/customers', async (request) => {
    const principal = await authenticate(request, 'customers:read');
    const query = z.object({ cursor: z.string().uuid().optional(), limit: z.coerce.number().int().min(1).max(100).default(20) }).parse(request.query);
    return { data: await repository.list(principal.merchantId, query.cursor, query.limit) };
  });
  app.get('/v1/customers/:id', async (request, reply) => {
    const principal = await authenticate(request, 'customers:read');
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const customer = await repository.find(principal.merchantId, id);
    if (!customer || customer.status === 'erased') return reply.code(404).send({ error: 'customer_not_found' });
    return customer;
  });
  app.post('/v1/customers/:id/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const key = request.headers['idempotency-key'];
    if (!isValidErasureIdempotencyKey(key)) return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    const result = await erasure.request(principal.merchantId, id, key);
    if (!result) return reply.code(404).send({ error: 'customer_not_found' });
    return reply.code(202).send(result);
  });
  app.get('/v1/erasure-requests/:requestId', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { requestId } = z.object({ requestId: z.string().uuid() }).parse(request.params);
    const found = await erasure.find(principal.merchantId, requestId);
    return found ?? reply.code(404).send({ error: 'erasure_request_not_found' });
  });

