        [
          event.merchantId,
          customerId ?? null,
          `anon_${event.aggregateId}`,
          event.eventType,
          erased ? null : event.payload.email ?? event.payload.customerEmail ?? null,
          erased ? scrubPayload(event.payload) : event.payload,
          event.occurredAt,
          event.eventId,
        ],
      );

